Svc <- list(
  get_a = function(self) { self$a },
  get_b = function(self) { self$b },
  get_c = function(self) { self$c },
  get_d = function(self) { self$d },
  set_a = function(self, v) { self$a <- v },
  set_b = function(self, v) { self$b <- v },
  set_c = function(self, v) { self$c <- v },
  set_d = function(self, v) { self$d <- v }
)
